{"path": "process_logs.py", "content": """"Summarize log severities over date ranges.

Reads the reference date from reference_date.txt, scans ./logs/*.log
(filenames: YYYY-MM-DD_<source>.log) and writes ./summary.csv.
"""
import csv
import glob
import os
import re
from datetime import date, timedelta

SEVERITIES = ["ERROR", "WARNING", "INFO"]
PERIODS = ["today", "last_7_days", "last_30_days", "month_to_date", "total"]
FILENAME_RE = re.compile(r"^(\d{4}-\d{2}-\d{2})_.+\.log$")


def read_reference_date(path="reference_date.txt"):
    with open(path, encoding="utf-8") as fh:
        return date.fromisoformat(fh.read().strip())


def count_severities(path):
    counts = {s: 0 for s in SEVERITIES}
    with open(path, encoding="utf-8") as fh:
        for line in fh:
            for sev in SEVERITIES:
                if sev in line:
                    counts[sev] += 1
                    break
    return counts


def main():
    today = read_reference_date()
    ranges = {
        "today": (today, today),
        "last_7_days": (today - timedelta(days=6), today),
        "last_30_days": (today - timedelta(days=29), today),
        "month_to_date": (today.replace(day=1), today),
    }

    totals = {p: {s: 0 for s in SEVERITIES} for p in PERIODS}

    for path in sorted(glob.glob(os.path.join("logs", "*.log"))):
        m = FILENAME_RE.match(os.path.basename(path))
        if not m:
            continue
        file_date = date.fromisoformat(m.group(1))
        counts = count_severities(path)
        for sev in SEVERITIES:
            totals["total"][sev] += counts[sev]
        for period, (start, end) in ranges.items():
            if start <= file_date <= end:
                for sev in SEVERITIES:
                    totals[period][sev] += counts[sev]

    with open("summary.csv", "w", newline="", encoding="utf-8") as fh:
        writer = csv.writer(fh)
        writer.writerow(["period", "severity", "count"])
        for period in PERIODS:
            for sev in SEVERITIES:
                writer.writerow([period, sev, totals[period][sev]])

    print("reference date:", today)
    for period in PERIODS:
        print(period, totals[period])


if __name__ == "__main__":
    main()
"}

